export type Lang = 'en' | 'ka'
export type TKey = keyof Dict
const dicts: Record<Lang, Dict> = { en, ka }

type Vars = Record<string, string | number>
const fill = (s: string, vars?: Vars) => vars ? s.replace(/\{(\w+)\}/g, (_, k) => String(vars[k] ?? '')) : s

const Ctx = createContext<{ lang: Lang; setLang: (l: Lang) => void; t: (k: TKey, vars?: Vars) => string }>(null!)

function storedLang(): Lang {
  try {
    const v = localStorage.getItem('lang')
    if (v === 'en' || v === 'ka') return v
  } catch { /* storage unavailable */ }
  return 'en'
}

export function I18nProvider({ children }: { children: ReactNode }) {
  const [lang, setLangState] = useState<Lang>(storedLang)
  const setLang = (l: Lang) => {
    setLangState(l)
    try { localStorage.setItem('lang', l) } catch { /* ignore */ }
  }
  return <Ctx.Provider value={{ lang, setLang, t: (k, vars) => fill(dicts[lang][k], vars) }}>{children}</Ctx.Provider>
}

export const useI18n = () => useContext(Ctx)
